import{createContext,runTool,TOOL_LABELS}from'../agents/tool-registry.js';
export function analyzeDataset(rows,{quality=null,onStep=()=>{}}={}){const ctx=createContext(rows,quality),tools=['analyze_member_engagement','analyze_promotion_timing','analyze_signup_engagement','compare_recent_formats','validate_dataset','calculate_attendance_metrics','calculate_attendance_trend','compare_meeting_types','compare_promotion_channels','analyze_social_reach','calculate_conversion_rate','calculate_retention','detect_attendance_anomalies','forecast_attendance','generate_club_health_summary','compare_prediction_to_actual','recommend_next_steps'],outputs={},steps=[];for(const name of tools){try{outputs[name]=runTool(name,ctx);steps.push({name,label:TOOL_LABELS[name],status:outputs[name].available===false?'limited':'complete'})}catch{outputs[name]={available:false,warnings:['This analysis is unavailable; other analyses are still available.']};steps.push({name,label:TOOL_LABELS[name],status:'unavailable'})}onStep(steps.at(-1))}return{rows:ctx.rows,quality:ctx.quality,outputs,steps}}
